function photo(src,alt,cls='',fallbackLabel=alt){return `<div class="${cls} photo-container"><img loading="lazy" src="${E(src)}" alt="${E(alt)}" onerror="this.hidden=true; this.nextElementSibling.hidden=false"><div class="image-fallback" hidden><span class="fallback-icon">✳</span>${E(fallbackLabel)}<small>Изображение временно недоступно</small></div></div>`}
