function appHeader(){const pub=['/','/about','/articles','/events','/contacts'];const isPublic=pub.includes(path())||path().startsWith('/articles/');const pubNav=[['/','Главная'],['/about','Об академии'],['/articles','Статьи'],['/events','Мастер-классы'],['/contacts','Контакты']];return `<div class="demo-bar">JUICY ACADEMY · ИНТЕРАКТИВНОЕ ДЕМО · <button data-go="preview">Проверить роли ↗</button> · Реальные видео, вход и отправка ещё не подключены</div>${isPublic?`<header class="header"><div class="wrap nav"><a class="logo" href="#/"><strong>JUICY</strong><small>BY NAZERKE</small></a><nav class="links ${state.menu?'open':''}">${pubNav.map(([u,n])=>`<a href="#${u}" class="${path()===u?'active':''}">${n}</a>`).join('')}</nav><div class="actions"><button class="btn btn-dark btn-small" data-go="academy">Войти ↗</button><button class="menu-btn" data-action="menu">☰</button></div></div></header>`:''}`}
