function aboutPage(){return `<main class="wrap about"><div class="portrait-frame about-photo">${photo(PIC+'nazerke-about.avif','Назерке с кухонной машиной Kenwood в светлом образе')}</div><div><div class="eyebrow">ДАВАЙТЕ ЗНАКОМИТЬСЯ</div><h1>Привет, я <em>Назерке.</em></h1><p class="lead">Эта академия создана, чтобы помогать владельцам Kenwood увереннее пользоваться техникой и готовить с удовольствием.</p><p>Здесь будут собраны уроки, рецепты, разбор насадок, тематические курсы и полезные рекомендации. Всё в понятной структуре, с возможностью возвращаться к материалам.</p><p>JUICY Academy будет постепенно расти вместе с новыми уроками и мастер-классами.</p><div class="notes">Личная биография, опыт и детали представительской деятельности будут внесены хозяйкой. В демо факты не выдумываем.</div><button class="btn btn-dark" data-go="academy">Посмотреть академию ↗</button></div></main>`}
function articlesPage(){return `<main class="wrap"><div class="page-head"><div class="eyebrow">ОТКРЫТЫЕ ПУБЛИКАЦИИ</div><h1>Заметки <em>с кухни.</em></h1><p>Полезные материалы для всех посетителей. Здесь нет закрытых видеоуроков и файлов академии.</p></div><div class="filters"><input id="article-search" placeholder="Найти статью..." aria-label="Поиск статей"></div><div class="cards" id="article-grid">${articles.map(a=>card({title:a.title,desc:a.desc,img:a.image,id:a.id,type:'public-article',caption:a.category,product:a.id!=='dough'})).join('')}</div></main>`}
function eventsPublic(){return `<main class="wrap"><div class="page-head"><div class="eyebrow">ВСТРЕЧАЕМСЯ И ГОТОВИМ</div><h1>Мастер-<em>классы.</em></h1><p>Здесь появятся реальные даты, города, программы и условия участия. Пока это примеры формата без записи на несуществующие мероприятия.</p></div><div class="cards">${[['День Италии',URLS.pasta,'Паста, пицца и итальянский стол'],['Қазақтың дастарханы',URLS.manti,'Манты и домашние блюда'],['Кондитер с нуля',URLS.biscuit,'Бисквит, кремы и оформление']].map((a,i)=>card({title:a[0],desc:a[2],img:a[1],id:'event'+i,type:'event',caption:'ПРИМЕР ПРОГРАММЫ'})).join('')}</div></main>`}
